insert into public.quiz_categories (slug, title)
values ('minecraft', 'MineMind Fan Quiz')
on conflict (slug) do nothing;

-- Per-locale packs from the first content release; kept for answer history.
update public.question_packs
set is_active = false
where locale is not null and slug like 'minecraft-%';

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, null, '8-12', 'easy', 'MineMind easy', 'minecraft-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active, v.kind, v.media, v.option_icons
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Hills with stripes of colored terracotta are a sign of which biome?', 'Savanna', 'Desert', 'Badlands', 'Plains', 2, 'Badlands hills are made of layers of colored terracotta and red sand.', 1, true, 'choice', null::jsonb, null::text[]),
  ('bamboo-jungle-has-bamboo', 'Pandas spawn most often in which biome?', 'Bamboo Jungle', 'Cherry Grove', 'Taiga', 'Savanna', 0, 'Pandas eat bamboo, so they show up most often in bamboo jungles.', 2, true, 'choice', null::jsonb, null::text[]),
  ('beach-is-sandy-shore', 'Which biome forms the sandy strip between land and ocean?', 'Desert', 'Beach', 'River', 'Stony Shore', 1, 'Beaches are thin sandy borders where land meets the ocean, and turtles spawn there.', 3, true, 'choice', null::jsonb, null::text[]),
  ('cherry-grove-has-pink-trees', 'Which biome is known for trees with pink leaves?', 'Flower Forest', 'Meadow', 'Cherry Grove', 'Birch Forest', 2, 'Cherry groves are full of cherry trees whose pink petals drift to the ground.', 4, true, 'choice', null::jsonb, null::text[]),
  ('desert-has-no-rain', 'In which biome does it never rain?', 'Plains', 'Jungle', 'Forest', 'Desert', 3, 'Deserts are too hot and dry for rain, so storms only darken the sky there.', 5, true, 'choice', null::jsonb, null::text[]),
  ('jungle-has-vines', 'Which biome has giant trees covered in vines and cocoa pods?', 'Dark Forest', 'Taiga', 'Jungle', 'Birch Forest', 2, 'Jungles grow huge trees wrapped in vines, with cocoa pods on their trunks.', 6, true, 'choice', null::jsonb, null::text[]),
  ('mushroom-fields-has-giant-mushrooms', 'Which rare island biome has purple-gray ground and red-spotted cows?', 'Swamp', 'Mushroom Fields', 'Dark Forest', 'Beach', 1, 'Mushroom fields are ocean islands covered in mycelium, home to mooshrooms.', 7, true, 'choice', null::jsonb, null::text[]),
  ('ocean-mostly-water', 'Dolphins swim in which large, deep-water biome?', 'Swamp', 'Ocean', 'River', 'Mangrove Swamp', 1, 'Dolphins spawn in oceans, and swimming next to them gives you a speed boost.', 8, true, 'choice', null::jsonb, null::text[]),
  ('plains-open-grassland', 'Which biome is flat and grassy with only a few scattered trees?', 'Jungle', 'Forest', 'Taiga', 'Plains', 3, 'Plains are wide grasslands with rare oak trees, where horses and villages are common.', 9, true, 'choice', null::jsonb, null::text[]),
  ('river-cuts-through-land', 'Which biome is a long, winding strip of water across the land?', 'River', 'Swamp', 'Ocean', 'Beach', 0, 'Rivers snake between other biomes, and salmon swim in them.', 10, true, 'choice', null::jsonb, null::text[]),
  ('savanna-has-acacia-trees', 'Where would a player find acacia trees most often?', 'Savanna', 'Dark Forest', 'Taiga', 'Birch Forest', 0, 'Savannas are dry grasslands dotted with flat-topped acacia trees.', 11, true, 'choice', null::jsonb, null::text[]),
  ('snowy-plains-has-snow', 'Which biome is flat, frozen land with almost no trees?', 'Snowy Plains', 'Snowy Taiga', 'Snowy Slopes', 'Frozen Ocean', 0, 'Snowy plains are flat fields of snow where water freezes into ice.', 12, true, 'choice', null::jsonb, null::text[]),
  ('swamp-has-lily-pads', 'Which biome has murky green water full of lily pads?', 'Jungle', 'Swamp', 'River', 'Taiga', 1, 'Swamps have murky water, lily pads and oak trees draped in vines.', 13, true, 'choice', null::jsonb, null::text[]),
  ('taiga-has-spruce', 'Which tree is especially common in a taiga?', 'Acacia', 'Mangrove', 'Spruce', 'Cherry', 2, 'Taigas are chilly forests full of spruce trees and sweet berry bushes.', 14, true, 'choice', null::jsonb, null::text[]),
  ('village-has-villagers', 'Which structure has houses, crop fields and a bell?', 'Pillager Outpost', 'Village', 'Igloo', 'Ruined Portal', 1, 'Villages give shelter, food and trades, and villagers gather at the bell.', 15, true, 'choice', null::jsonb, null::text[]),
  ('cobblestone-from-stone', 'What block drops when you mine stone with a normal pickaxe?', 'Smooth Stone', 'Gravel', 'Stone Bricks', 'Cobblestone', 3, 'Stone breaks into cobblestone unless your pickaxe has Silk Touch, which keeps it as stone.', 16, true, 'choice', null::jsonb, null::text[]),
  ('glass-is-see-through', 'Which block can you see through, making it great for windows?', 'Glass', 'Terracotta', 'Cobblestone', 'Wool', 0, 'Glass is transparent, so it lets light in and lets you watch outside while keeping mobs out.', 17, true, 'choice', null::jsonb, null::text[]),
  ('obsidian-from-water-and-lava', 'What block forms when water flows onto a lava source block?', 'Basalt', 'Obsidian', 'Magma Block', 'Clay', 1, 'Water turns a lava source into obsidian, which is how many players get blocks for a Nether portal.', 18, true, 'choice', null::jsonb, null::text[]),
  ('planks-build-starter-house', 'How many planks do you get from crafting one log?', '4', '8', '2', '6', 0, 'One log always gives four planks, just enough for a crafting table.', 19, true, 'choice', null::jsonb, null::text[]),
  ('sand-falls-with-gravity', 'Which block falls down if there is no block under it?', 'Oak Planks', 'Sand', 'Stone Bricks', 'Bookshelf', 1, 'Sand obeys gravity, so it drops as soon as the block below it is gone.', 20, true, 'choice', null::jsonb, null::text[]),
  ('ladder-climbs-wall', 'Which block lets you climb straight up a wall?', 'Ladder', 'Fence', 'Carpet', 'Glass Pane', 0, 'Ladders attach to the side of a block and let you climb up or down vertically.', 21, true, 'choice', null::jsonb, null::text[]),
  ('slab-is-half-block', 'Which building block is exactly half as tall as a full block?', 'Stairs', 'Carpet', 'Slab', 'Trapdoor', 2, 'Slabs are half-height, perfect for smooth floors, roofs and small steps.', 22, true, 'choice', null::jsonb, null::text[]),
  ('trapdoor-covers-hole', 'Which hinged block lies flat and can cover a one-block hole in the floor?', 'Pressure Plate', 'Fence Gate', 'Door', 'Trapdoor', 3, 'A trapdoor flips open and shut over a single block space, making it a perfect floor hatch.', 23, true, 'choice', null::jsonb, null::text[]),
  ('coal-fuels-furnace', 'Which item is the most common fuel for a furnace?', 'Sand', 'Coal', 'Cobblestone', 'String', 1, 'One piece of coal burns long enough to smelt 8 items, so it is the go-to furnace fuel.', 24, true, 'choice', null::jsonb, null::text[]),
  ('crafting-table-basics', 'Which block gives you a 3×3 grid for making tools and items?', 'Chest', 'Crafting Table', 'Furnace', 'Bed', 1, 'Your inventory only has a 2×2 grid, so bigger recipes like tools need a crafting table.', 25, true, 'choice', null::jsonb, null::text[]),
  ('furnace-smelts-raw-iron', 'Which block turns raw iron into iron ingots when you add fuel?', 'Barrel', 'Furnace', 'Composter', 'Anvil', 1, 'A furnace burns fuel to smelt ores, so raw iron comes out as ingots.', 26, true, 'choice', null::jsonb, null::text[]),
  ('planks-from-logs', 'How many iron ingots does it take to craft a block of iron?', '6', '9', '4', '8', 1, 'Nine ingots fill the whole 3×3 grid, and the block can be turned back into nine ingots.', 27, true, 'choice', null::jsonb, null::text[]),
  ('sticks-from-planks', 'Which item made from planks is the handle in most tool recipes?', 'Ladder', 'Button', 'Bowl', 'Stick', 3, 'Two planks stacked make four sticks, and tools, torches and signs all need them.', 28, true, 'choice', null::jsonb, null::text[]),
  ('pickaxe-mines-stone', 'Which tool do you need for mined stone to drop anything?', 'Axe', 'Shovel', 'Pickaxe', 'Hoe', 2, 'Stone mined by hand or with any other tool drops nothing, so a pickaxe is required.', 29, true, 'choice', null::jsonb, null::text[]),
  ('carrots-breed-pigs', 'Which food can you use to breed pigs?', 'Wheat', 'Carrot', 'Kelp', 'Red Mushroom', 1, 'Pigs love root crops: carrots, potatoes and beetroots all make them breed, but wheat does not.', 30, true, 'choice', null::jsonb, null::text[]),
  ('chickens-lay-eggs', 'What does a chicken drop by itself every few minutes?', 'Feather', 'Egg', 'Leather', 'Wheat Seeds', 1, 'Chickens lay an egg every 5–10 minutes; feathers only drop when a chicken is killed.', 31, true, 'choice', null::jsonb, null::text[]),
  ('cow-drops-leather', 'Which animal can drop leather?', 'Cow', 'Pig', 'Sheep', 'Chicken', 0, 'Cows drop leather and raw beef, so a cow farm gives you both food and leather for books and armor.', 32, true, 'choice', null::jsonb, null::text[]),
  ('sheep-give-wool', 'Which animal can you shear to get wool?', 'Goat', 'Cow', 'Pig', 'Sheep', 3, 'Sheared sheep regrow their wool after eating grass, so they give wool again and again.', 33, true, 'choice', null::jsonb, null::text[]),
  ('wheat-grows-from-seeds', 'Breaking grass can drop seeds. Which crop do they grow into?', 'Carrot', 'Cactus', 'Sugar Cane', 'Wheat', 3, 'Grass drops wheat seeds, which is why wheat is usually the very first crop a new player plants.', 34, true, 'choice', null::jsonb, null::text[]),
  ('bone-meal-speeds-growth', 'Which item makes crops grow faster when you use it on them?', 'Paper', 'Bone Meal', 'Gunpowder', 'Sugar', 1, 'Bone meal pushes a crop forward one or more growth stages at once, so you don''t have to wait.', 35, true, 'choice', null::jsonb, null::text[]),
  ('bucket-collects-cow-milk', 'What do you use on a cow to collect milk?', 'Glass Bottle', 'Bowl', 'Bucket', 'Shears', 2, 'Milk is a liquid like water, so it is carried in a bucket; a milk bucket also removes potion effects.', 36, true, 'choice', null::jsonb, null::text[]),
  ('hoe-makes-farmland', 'Which tool turns dirt into farmland?', 'Pickaxe', 'Hoe', 'Shears', 'Shovel', 1, 'Seeds can only be planted on farmland, so tilling dirt with a hoe is the first step of any farm.', 37, true, 'choice', null::jsonb, null::text[]),
  ('creeper-explodes', 'Which hostile mob hisses right before it explodes?', 'Creeper', 'Zombie', 'Skeleton', 'Spider', 0, 'Creepers sneak up silently, hiss for a moment and then blow up, damaging players and blocks.', 38, true, 'choice', null::jsonb, null::text[]),
  ('large-slime-splits', 'Which green bouncing mob splits into smaller copies when defeated?', 'Slime', 'Witch', 'Creeper', 'Enderman', 0, 'A big slime breaks into several smaller slimes, and the medium ones split again.', 39, true, 'choice', null::jsonb, null::text[]),
  ('skeleton-uses-bow', 'Which common hostile mob shoots arrows at you with a bow?', 'Creeper', 'Skeleton', 'Zombie', 'Slime', 1, 'Skeletons attack from range, so a shield or cover helps a lot against them.', 40, true, 'choice', null::jsonb, null::text[]),
  ('spider-climbs-walls', 'Which hostile mob can climb straight up walls?', 'Spider', 'Enderman', 'Creeper', 'Zombie', 0, 'Spiders climb vertical surfaces, so a plain wall won''t keep them out of your base.', 41, true, 'choice', null::jsonb, null::text[]),
  ('zombies-burn-in-day', 'Which of these mobs catches fire in direct sunlight?', 'Spider', 'Zombie', 'Creeper', 'Witch', 1, 'Zombies burn in daylight unless they stand in shade or water or wear a helmet.', 42, true, 'choice', null::jsonb, null::text[]),
  ('button-short-redstone-pulse', 'Which redstone power source turns on for a moment, then switches off by itself?', 'Block of Redstone', 'Redstone Torch', 'Button', 'Lever', 2, 'A button gives a short pulse and turns off, while a lever, torch or redstone block stays powered.', 43, true, 'choice', null::jsonb, null::text[]),
  ('flint-and-steel-lights-portal', 'Which tool do players usually use to light a Nether portal?', 'Flint and Steel', 'Shears', 'Compass', 'Spyglass', 0, 'Flint and steel sets fire inside the obsidian frame, which turns it into a working portal.', 44, true, 'choice', null::jsonb, null::text[]),
  ('nether-portal-needs-obsidian', 'Which block is a Nether portal frame built from?', 'Cobblestone', 'Netherrack', 'Obsidian', 'Blackstone', 2, 'Only obsidian works for the frame; mine it with a diamond pickaxe or make it from water and lava.', 45, true, 'choice', null::jsonb, null::text[]),
  ('redstone-dust-carries-power', 'Which dust is laid on the ground like a wire to carry a signal from a lever to a piston?', 'Sugar', 'Redstone Dust', 'Gunpowder', 'Glowstone Dust', 1, 'Redstone dust forms wires that carry a signal up to 15 blocks before it fades out.', 46, true, 'choice', null::jsonb, null::text[]),
  ('soul-sand-slows-movement', 'Which Nether block slows you down when you walk on it?', 'Netherrack', 'Blackstone', 'Basalt', 'Soul Sand', 3, 'Soul sand is slightly lower than a full block, so you sink in and walk more slowly.', 47, true, 'choice', null::jsonb, null::text[]),
  ('lever-toggles-circuit', 'Which switch stays on or off until you flip it again?', 'Lever', 'Button', 'Pressure Plate', 'Tripwire Hook', 0, 'A lever keeps its position and gives steady power, while buttons and plates switch off by themselves.', 48, true, 'choice', null::jsonb, null::text[]),
  ('bed-sets-respawn', 'Which item lets you sleep and set your respawn point?', 'Boat', 'Chest', 'Bed', 'Banner', 2, 'Sleeping in a bed skips the night and sets your respawn point next to it.', 49, true, 'choice', null::jsonb, null::text[]),
  ('cooked-food-better-hunger', 'Which of these foods restores the most hunger?', 'Melon Slice', 'Cooked Porkchop', 'Raw Porkchop', 'Apple', 1, 'Cooked porkchop restores 8 hunger points, far more than raw meat, an apple or melon.', 50, true, 'choice', null::jsonb, null::text[]),
  ('eating-refills-hunger', 'Which bar fills up when you eat food?', 'Air Bar', 'Armor Bar', 'Experience Bar', 'Hunger Bar', 3, 'Food refills the hunger bar, and a full bar lets you sprint and regenerate health.', 51, true, 'choice', null::jsonb, null::text[]),
  ('shelter-before-first-night', 'What should you build before your first night to stay safe?', 'Nether Portal', 'Shelter', 'Beacon', 'Enchanting Table', 1, 'Hostile mobs spawn in the dark, so a simple closed shelter keeps you safe on night one.', 52, true, 'choice', null::jsonb, null::text[]),
  ('torch-lights-caves', 'What do players place to light up dark caves?', 'Door', 'Sign', 'Torch', 'Chest', 2, 'Torches give off light, so you can see in caves and fewer monsters spawn nearby.', 53, true, 'choice', null::jsonb, null::text[]),
  ('barrel-makes-fisherman', 'Which job block turns a villager into a fisherman?', 'Cauldron', 'Smoker', 'Composter', 'Barrel', 3, 'A villager that claims a barrel becomes a fisherman, who trades fish and fishing rods.', 54, true, 'choice', null::jsonb, null::text[]),
  ('bookshelves-boost-enchanting', 'Which block placed around an enchanting table unlocks stronger enchantments?', 'Barrel', 'Bookshelf', 'Lectern', 'Lantern', 1, 'Each bookshelf near the table raises the enchantment levels it offers, up to level 30.', 55, true, 'choice', null::jsonb, null::text[]),
  ('composter-makes-farmer', 'Which job block turns a villager into a farmer?', 'Barrel', 'Loom', 'Smoker', 'Composter', 3, 'Villagers take the job of the block they claim, and the composter belongs to farmers.', 56, true, 'choice', null::jsonb, null::text[]),
  ('emeralds-for-trading', 'Which gem do villagers use as money when trading?', 'Diamond', 'Nether Quartz', 'Amethyst Shard', 'Emerald', 3, 'Villagers buy and sell almost everything for emeralds, so they work like village money.', 57, true, 'choice', null::jsonb, null::text[]),
  ('lapis-for-enchanting', 'Which item does an enchanting table use up along with your levels?', 'Redstone Dust', 'Lapis Lazuli', 'Amethyst Shard', 'Diamond', 1, 'Each enchantment at the table costs 1 to 3 lapis lazuli, placed in the slot next to the item.', 58, true, 'choice', null::jsonb, null::text[]),
  ('librarian-sells-books', 'Which villager can sell you enchanted books?', 'Librarian', 'Cartographer', 'Farmer', 'Cleric', 0, 'Librarians trade enchanted books for emeralds and books, even rare ones like Mending.', 59, true, 'choice', null::jsonb, null::text[]),
  ('villagers-sleep-in-beds', 'What do villagers sleep in at night?', 'Bed', 'Carpet', 'Barrel', 'Hay Bale', 0, 'Every villager claims a bed as its home and goes to sleep in it when night falls.', 60, true, 'choice', null::jsonb, null::text[]),
  ('anvil-can-rename-items', 'Which helmet enchantment lets you stay underwater longer before running out of air?', 'Protection', 'Respiration', 'Depth Strider', 'Aqua Affinity', 1, 'Respiration adds extra time before you start drowning, and each level adds more.', 61, true, 'choice', null::jsonb, null::text[]),
  ('enchanted-books-applied-with-anvil', 'Which boot enchantment reduces fall damage?', 'Thorns', 'Soul Speed', 'Depth Strider', 'Feather Falling', 3, 'Feather Falling softens hard landings, and at level IV it saves you from many big drops.', 62, true, 'choice', null::jsonb, null::text[]),
  ('lectern-makes-librarian', 'Which job block turns a villager into a librarian?', 'Lectern', 'Composter', 'Cauldron', 'Brewing Stand', 0, 'The lectern is the librarian''s job block, so placing one near an unemployed villager gets you a librarian.', 63, true, 'choice', null::jsonb, null::text[]),
  ('three-enchanting-choices', 'How many enchantment options does an enchanting table show at once?', '6', '1', '4', '3', 3, 'The table always shows three options, and each lower one costs more lapis and levels.', 64, true, 'choice', null::jsonb, null::text[]),
  ('unemployed-villager-claims-job-block', 'What must an unemployed villager claim to start trading?', 'Campfire', 'Job block', 'Bed', 'Bell', 1, 'A villager with no profession can''t trade until it links to a free job block like a lectern.', 65, true, 'choice', null::jsonb, null::text[]),
  ('efficiency-speeds-mining', 'Which enchantment makes a pickaxe dig faster?', 'Unbreaking', 'Fortune', 'Efficiency', 'Sharpness', 2, 'Efficiency raises mining speed, and each higher level makes digging even quicker.', 66, true, 'choice', null::jsonb, null::text[]),
  ('protection-reduces-damage', 'Which armor enchantment lowers damage from almost every source?', 'Depth Strider', 'Respiration', 'Feather Falling', 'Protection', 3, 'Protection cuts most kinds of damage, unlike Fire or Blast Protection, which guard against one danger.', 67, true, 'choice', null::jsonb, null::text[]),
  ('silk-touch-drops-glass', 'Which sword enchantment sets the mobs you hit on fire?', 'Looting', 'Fire Aspect', 'Smite', 'Knockback', 1, 'Fire Aspect burns mobs after each hit, and animals defeated this way drop cooked meat.', 68, true, 'choice', null::jsonb, null::text[]),
  ('hearts-show-player-health', 'Which icons on the screen show your health?', 'Armor Icons', 'Bubbles', 'Hearts', 'Drumsticks', 2, 'Each full heart is 2 health points, and losing them all means you die.', 69, true, 'choice', null::jsonb, null::text[]),
  ('armor-cuts-incoming-damage', 'Which equipment reduces the damage mobs deal to you?', 'Saddle', 'Shears', 'Compass', 'Armor', 3, 'Each armor piece adds armor points, and more points mean less damage from hits.', 70, true, 'choice', null::jsonb, null::text[]),
  ('night-more-hostile-spawns', 'Which item shows whether it is day or night, even deep underground?', 'Clock', 'Compass', 'Recovery Compass', 'Spyglass', 0, 'A clock''s dial shows the sun and moon, so you know when it''s safe to leave your shelter.', 71, true, 'choice', null::jsonb, null::text[]),
  ('door-closes-base-entrance', 'Which block at a shelter entrance keeps mobs out but lets you pass?', 'Flower Pot', 'Door', 'Painting', 'Carpet', 1, 'You can open and close a door yourself, while most mobs cannot get through it.', 72, true, 'choice', null::jsonb, null::text[]),
  ('wool-used-for-bed', 'Which block is a carved pumpkin with a torch inside?', 'Sea Lantern', 'Jack o''Lantern', 'Glowstone', 'Lantern', 1, 'A jack o''lantern glows like a torch, so it lights up your shelter and even shines underwater.', 73, true, 'choice', null::jsonb, null::text[]),
  ('ladder-climbs-vertical-wall', 'Which plant hurts you when you touch it?', 'Dead Bush', 'Bamboo', 'Sugar Cane', 'Cactus', 3, 'A cactus damages anyone who touches it, so keep it away from paths and animal pens.', 74, true, 'choice', null::jsonb, null::text[]),
  ('boat-travels-over-water', 'Which item lets you travel quickly across a river or ocean?', 'Lead', 'Minecart', 'Boat', 'Saddle', 2, 'A boat floats on water and moves much faster than swimming.', 75, true, 'choice', null::jsonb, null::text[]),
  ('torch-brightens-dark-spaces', 'Besides a stick, what do you need to craft a torch?', 'Flint', 'Gunpowder', 'Bone', 'Coal', 3, 'A torch is coal or charcoal placed on top of a stick.', 76, true, 'choice', null::jsonb, null::text[]),
  ('sneaking-prevents-edge-fall', 'Which action stops you from walking off a block edge?', 'Swimming', 'Sneaking', 'Gliding', 'Sprinting', 1, 'While sneaking you stop at the edge of a block, which makes building high up safer.', 77, true, 'choice', null::jsonb, null::text[]),
  ('bucket-picks-up-water-source', 'Which item lets you pick up a water source block?', 'Bucket', 'Bowl', 'Cauldron', 'Flower Pot', 0, 'An empty bucket scoops up a water or lava source block so you can place it elsewhere.', 78, true, 'choice', null::jsonb, null::text[]),
  ('chest-stores-home-items', 'Which block do players usually craft to store lots of items at home?', 'Lantern', 'Chest', 'Bed', 'Furnace', 1, 'A chest holds 27 stacks, and two side by side become a large double chest.', 79, true, 'choice', null::jsonb, null::text[]),
  ('bed-crafted-from-wool-and-planks', 'Which item is crafted from three wool and three planks?', 'Boat', 'Bed', 'Shield', 'Ladder', 1, 'Sleeping in a bed skips the night and sets your respawn point.', 80, true, 'choice', null::jsonb, null::text[]),
  ('furnace-crafted-from-cobblestone', 'Which block is crafted from eight cobblestone placed in a ring?', 'Furnace', 'Anvil', 'Dispenser', 'Barrel', 0, 'Eight cobblestone around an empty center make a furnace for smelting ores and cooking food.', 81, true, 'choice', null::jsonb, null::text[]),
  ('four-planks-make-crafting-table', 'Which block do four planks make in the 2×2 inventory grid?', 'Barrel', 'Crafting Table', 'Bookshelf', 'Chest', 1, 'Four planks in a square make a crafting table, your first step toward bigger recipes.', 82, true, 'choice', null::jsonb, null::text[]),
  ('planks-work-as-furnace-fuel', 'Out of coal? Which of these can also fuel a furnace?', 'Planks', 'Stone', 'Glass', 'Gravel', 0, 'Wooden things burn in a furnace, and one plank smelts one and a half items.', 83, true, 'choice', null::jsonb, null::text[]),
  ('pickaxe-breaks-stone-faster', 'Which tool chops logs the fastest?', 'Shears', 'Axe', 'Shovel', 'Pickaxe', 1, 'Axes are made for wood, so logs and planks break much faster with one.', 84, true, 'choice', null::jsonb, null::text[]),
  ('stone-drops-cobblestone', 'How many diamonds does it take to craft a diamond pickaxe?', '3', '2', '5', '4', 0, 'A pickaxe needs three pieces of its material across the top and two sticks below.', 85, true, 'choice', null::jsonb, null::text[]),
  ('iron-ingots-craft-bucket', 'Which ingot is used to craft a bucket?', 'Iron Ingot', 'Netherite Ingot', 'Gold Ingot', 'Copper Ingot', 0, 'Three iron ingots in a V shape make a bucket for water, lava or milk.', 86, true, 'choice', null::jsonb, null::text[]),
  ('stone-next-tier-after-wood', 'Which tool material comes right after wood in the usual upgrade path?', 'Diamond', 'Netherite', 'Iron', 'Stone', 3, 'Stone tools need only cobblestone and sticks, yet last longer and dig faster than wooden ones.', 87, true, 'choice', null::jsonb, null::text[]),
  ('logs-turn-into-planks', 'Which part of a tree do you put in the crafting grid to get planks?', 'Sapling', 'Log', 'Leaves', 'Stick', 1, 'Logs are chopped from tree trunks, and each one crafts into planks for building.', 88, true, 'choice', null::jsonb, null::text[]),
  ('dirt-under-many-grass-blocks', 'What do you get when you dig up a grass block without Silk Touch?', 'Grass Block', 'Coarse Dirt', 'Dirt', 'Gravel', 2, 'Without Silk Touch the grass layer is lost, and the block drops as plain dirt.', 89, true, 'choice', null::jsonb, null::text[]),
  ('stairs-help-players-climb-builds', 'Which block can you walk up onto without jumping?', 'Glass Pane', 'Stairs', 'Fence', 'Chest', 1, 'Stairs rise in half-block steps, so you can walk up them without pressing jump.', 90, true, 'choice', null::jsonb, null::text[]),
  ('gravel-falls-like-sand', 'Which block sometimes drops flint when you dig it?', 'Clay', 'Dirt', 'Gravel', 'Sand', 2, 'Gravel has a small chance to drop flint, which you need for arrows and flint and steel.', 91, true, 'choice', null::jsonb, null::text[]),
  ('sandstone-crafted-from-sand', 'Which tree has white bark with black marks?', 'Spruce', 'Oak', 'Acacia', 'Birch', 3, 'Birch logs are white with dark spots, which makes birch forests easy to spot from far away.', 92, true, 'choice', null::jsonb, null::text[]),
  ('axe-creates-stripped-log', 'Which tool strips the bark off a log when you use it?', 'Hoe', 'Axe', 'Sword', 'Shovel', 1, 'Using an axe on a log or wood block strips off its bark for a cleaner look.', 93, true, 'choice', null::jsonb, null::text[]),
  ('leaves-decay-without-nearby-log', 'What do decaying tree leaves sometimes drop?', 'String', 'Seeds', 'Sapling', 'Bone Meal', 2, 'Leaves left without logs slowly decay and can drop saplings, so you can replant the tree.', 94, true, 'choice', null::jsonb, null::text[]),
  ('wheat-breeds-cows-and-sheep', 'Which crop can you use to breed cows and sheep?', 'Carrot', 'Potato', 'Beetroot', 'Wheat', 3, 'Cows, sheep and goats all eat wheat, so one wheat field can feed most of your farm animals.', 95, true, 'choice', null::jsonb, null::text[]),
  ('carrot-plants-more-carrots', 'Which crop is planted from the crop itself, with no seeds item?', 'Carrot', 'Wheat', 'Pumpkin', 'Beetroot', 0, 'Carrots, like potatoes, have no seeds: you plant a carrot and harvest several more carrots.', 96, true, 'choice', null::jsonb, null::text[]),
  ('melon-block-grows-from-melon-stem', 'Which crop block drops slices when you break it?', 'Pumpkin', 'Cactus', 'Melon', 'Hay Bale', 2, 'A melon block breaks into 3–7 slices, while a pumpkin drops itself as a whole block.', 97, true, 'choice', null::jsonb, null::text[]),
  ('three-wheat-craft-bread', 'What does raw beef turn into when you cook it in a furnace?', 'Cooked Chicken', 'Steak', 'Cooked Porkchop', 'Cooked Mutton', 1, 'Cooked beef is called steak, and it fills as much hunger as a cooked porkchop.', 98, true, 'choice', null::jsonb, null::text[]),
  ('bowl-carries-mushroom-stew', 'Besides a red and a brown mushroom, what do you need to craft mushroom stew?', 'Bucket', 'Stick', 'Bowl', 'Glass Bottle', 2, 'Stew is served in a bowl, and you get the empty bowl back after eating it.', 99, true, 'choice', null::jsonb, null::text[]),
  ('hay-bale-stores-extra-wheat', 'Which block is crafted from nine wheat?', 'Moss Block', 'Dried Kelp Block', 'Hay Bale', 'White Wool', 2, 'A hay bale packs nine wheat into one block, saving chest space and feeding horses and llamas.', 100, true, 'choice', null::jsonb, null::text[]),
  ('pandas-breed-with-bamboo', 'Which plant do you feed pandas to breed them?', 'Bamboo', 'Sugar Cane', 'Wheat', 'Kelp', 0, 'Pandas live in bamboo jungles and eat bamboo, so it is the food that makes them breed.', 101, true, 'choice', null::jsonb, null::text[]),
  ('cow-makes-moo-sound', 'Which sea creature drops ink sacs?', 'Cod', 'Squid', 'Dolphin', 'Turtle', 1, 'Squids drop ink sacs, which you use to make black dye and a book and quill.', 102, true, 'choice', null::jsonb, null::text[]),
  ('sheep-can-be-sheared', 'Which small flying mob sleeps hanging upside down in dark caves?', 'Parrot', 'Bat', 'Allay', 'Bee', 1, 'Bats hang upside down from cave ceilings and flutter around when a player comes near.', 103, true, 'choice', null::jsonb, null::text[]),
  ('bee-produces-honey', 'Which small mob fills nests and hives with honey?', 'Bat', 'Bee', 'Parrot', 'Chicken', 1, 'Bees collect pollen from flowers and bring it home, slowly filling the nest with honey.', 104, true, 'choice', null::jsonb, null::text[]),
  ('wolf-can-be-tamed-as-pet', 'Which tamed animal can you ride after putting a saddle on it?', 'Parrot', 'Wolf', 'Horse', 'Cat', 2, 'Once a horse is tamed and saddled, you can ride and steer it much faster than walking.', 105, true, 'choice', null::jsonb, null::text[]),
  ('pig-likes-carrots', 'Which animal can you tame by feeding it seeds?', 'Cat', 'Chicken', 'Wolf', 'Parrot', 3, 'Feeding seeds tames a parrot, and after that it can ride on your shoulder.', 106, true, 'choice', null::jsonb, null::text[]),
  ('shield-blocks-many-hits', 'Besides sticks, which item do you need to craft a bow?', 'Leather', 'Feather', 'String', 'Wool', 2, 'Three sticks and three string make a bow, and spiders are the easiest source of string.', 107, true, 'choice', null::jsonb, null::text[]),
  ('sword-is-basic-melee-weapon', 'Which crafted item is made mainly for close-range fighting?', 'Sword', 'Hoe', 'Shovel', 'Bucket', 0, 'A sword is the basic melee weapon and deals more damage than tools like a hoe or shovel.', 108, true, 'choice', null::jsonb, null::text[]),
  ('bow-fires-arrows', 'Which weapon do you pull back to shoot arrows at faraway mobs?', 'Trident', 'Bow', 'Sword', 'Axe', 1, 'A bow lets you attack from a safe distance; the longer you pull it back, the harder it hits.', 109, true, 'choice', null::jsonb, null::text[]),
  ('armor-reduces-attack-damage', 'Which full armor set protects you the least?', 'Diamond Armor', 'Leather Armor', 'Netherite Armor', 'Iron Armor', 1, 'Leather is the weakest armor, while diamond and netherite give the most protection.', 110, true, 'choice', null::jsonb, null::text[]),
  ('torches-help-stop-spawns', 'Which sword deals the most damage?', 'Diamond Sword', 'Stone Sword', 'Netherite Sword', 'Iron Sword', 2, 'Netherite is the strongest material, so its sword hits harder than a diamond one and lasts longer.', 111, true, 'choice', null::jsonb, null::text[]),
  ('ender-pearl-drops-from-enderman', 'Which mob drops pearls that teleport you when thrown?', 'Phantom', 'Enderman', 'Shulker', 'Endermite', 1, 'Endermen drop ender pearls, which you also need later to craft Eyes of Ender.', 112, true, 'choice', null::jsonb, null::text[]),
  ('end-portal-opens-path-to-end', 'Which portal takes you from the Overworld to the dragon''s dimension?', 'Nether Portal', 'End Gateway', 'End Portal', 'Ruined Portal', 2, 'An End portal sits inside a stronghold and starts working once every frame holds an Eye of Ender.', 113, true, 'choice', null::jsonb, null::text[]),
  ('ender-dragon-is-end-boss', 'Which boss waits on the main island after you jump into the stronghold portal?', 'Elder Guardian', 'Warden', 'Ender Dragon', 'Wither', 2, 'The Ender Dragon guards the main island, and defeating it opens the exit portal back home.', 114, true, 'choice', null::jsonb, null::text[]),
  ('stronghold-contains-end-portal', 'End City towers are built from end stone bricks and which other block?', 'Block of Amethyst', 'Purpur Block', 'Crying Obsidian', 'Prismarine', 1, 'Purpur blocks give End cities their purple color, so they are the easiest place to collect them.', 115, true, 'choice', null::jsonb, null::text[]),
  ('end-stone-covers-end-islands', 'Which pale yellow block forms the ground of the dragon''s islands?', 'Smooth Stone', 'Bone Block', 'End Stone', 'Sandstone', 2, 'End stone makes up almost all the land in the End and holds up well against explosions.', 116, true, 'choice', null::jsonb, null::text[]),
  ('redstone-torch-provides-power', 'Which light source also gives constant power to circuits?', 'Torch', 'Redstone Torch', 'Soul Torch', 'Lantern', 1, 'A redstone torch stays on until the block it is attached to gets powered, which turns it off.', 117, true, 'choice', null::jsonb, null::text[]),
  ('pressure-plate-triggers-on-step', 'Which light block glows only while it is powered?', 'Sea Lantern', 'Glowstone', 'Shroomlight', 'Redstone Lamp', 3, 'A redstone lamp shines while it gets a signal and goes dark without one, unlike always-on light blocks.', 118, true, 'choice', null::jsonb, null::text[]),
  ('piston-pushes-block-forward', 'Which ore glows when you touch it or walk on it?', 'Coal Ore', 'Redstone Ore', 'Diamond Ore', 'Lapis Lazuli Ore', 1, 'Redstone ore lights up when touched and drops redstone dust, the wire of every circuit.', 119, true, 'choice', null::jsonb, null::text[]),
  ('strider-walks-on-lava', 'Which rideable mob can walk across Nether lava lakes?', 'Hoglin', 'Strider', 'Horse', 'Pig', 1, 'Striders walk on lava without burning, so with a saddle they carry you safely across.', 120, true, 'choice', null::jsonb, null::text[])
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
where pack.slug = 'minecraft-easy'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  kind = excluded.kind,
  media = excluded.media,
  option_icons = excluded.option_icons;

insert into public.question_translations (question_id, locale, prompt, option_a, option_b, option_c, option_d, explanation)
